#include <bits/stdc++.h>
using namespace std;

using ll = long long;
ll compute_mod_inverse(ll a, ll m) {
	assert(m > 0);
	if (m == 1) return 0;
	a %= m;
	if (a < 0) a += m;
	assert(a != 0);
	if (a == 1) return 1;
	return m - compute_mod_inverse(m, a) * m / a;
}

template <int MOD_> struct ModularType {
private:
	int val;
public:
	static const int MOD = MOD_;

	ModularType() : val(0) {}
	ModularType(ll v_) : val(int(v_ % MOD)) { if (val < 0) val += MOD; }
	explicit operator int () const { return val; }
	friend bool operator == (const ModularType& a, const ModularType& b) { return a.val == b.val; }
	friend bool operator != (const ModularType& a, const ModularType& b) { return a.val != b.val; }

	ModularType operator ~ () const {
		ModularType res;
		res.val = compute_mod_inverse(val, MOD);
		return res;
	}

	ModularType& operator += (const ModularType& o) {
		val += o.val;
		if (val >= MOD) val -= MOD;
		return *this;
	}
	ModularType& operator -= (const ModularType& o) {
		val -= o.val;
		if (val < 0) val += MOD;
		return *this;
	}
	ModularType& operator *= (const ModularType& o) {
		val = int(ll(val) * ll(o.val) % MOD);
		return *this;
	}
	ModularType& operator /= (const ModularType& o) {
		return *this *= (~o);
	}

	friend ModularType operator + (const ModularType& a, const ModularType& b) { return ModularType(a) += b; }
	friend ModularType operator - (const ModularType& a, const ModularType& b) { return ModularType(a) -= b; }
	friend ModularType operator * (const ModularType& a, const ModularType& b) { return ModularType(a) *= b; }
	friend ModularType operator / (const ModularType& a, const ModularType& b) { return ModularType(a) /= b; }
};

using modnum_type = ModularType<int(1e9)+7>;

int main() {
	ios_base::sync_with_stdio(0), cin.tie(0), cout.tie(0);
	const int n = 6;
	vector<vector<modnum_type>> p(n, vector<modnum_type>(n, 0));
	int _n;
	cin >> _n;
	for (int i = 0; i < n; i++) p[i][i] = 1;
	for (int i = 0; i < _n; i++) {
		for (int j = 0; j < _n; j++) {
			int a;
			cin >> a;
			p[i][j] = modnum_type(a) / modnum_type(100);
		}
	}
	const int f = 20;
	vector<vector<modnum_type>> sets(2, vector<modnum_type>(1 << f, 0));
	vector<vector<int>> masks(2);
	for (int i = 0; i < n; i++) {
		for (int j = 0; j < i; j++) {
			for (int k = 0; k < j; k++) {
				masks[0].push_back((1 << i) ^ (1 << j) ^ (1 << k));
				masks[1].push_back(((1 << n) - 1) ^ masks[0].back());
			}
		}
	}
	assert(f == (int)masks[0].size());
	for (int t = 0; t < 2; t++) {
		for (int e = 0; e < (1 << (n / 2 * n)); e++) {
			modnum_type prob = 1;
			int edges[n / 2];
			for (int i = 0; i < n / 2; i++) edges[i] = 0;
			for (int i = 0; i < n / 2 * n; i++) {
				bool r = (e >> i) & 1;
				modnum_type pp = p[(i / n) * 2 + t][i % n];
				prob *= r ? pp : (1 - pp);
				edges[i / n] |= int(r) << (i % n);
			}
			int work_mask = 0;
			for (int a = 0; a < (int)masks[t].size(); a++) {
				int mask = masks[t][a];
				int r[n / 2];
				for (int i = 0; i < n / 2; i++) r[i] = edges[i] & mask;
				if (r[0] && r[1] && r[2]) {
					if (__builtin_popcount(r[0] | r[1] | r[2]) == 3) {
						int x = __builtin_popcount(r[0] | r[1]);
						int y = __builtin_popcount(r[0] | r[2]);
						int z = __builtin_popcount(r[1] | r[2]);
						if (x >= 2 && y >= 2 && z >= 2) {
							work_mask |= (1 << a);
						}
					}
				}
			}
			sets[t][work_mask] += prob;
		}
	}
	for (int i = 0; i < f; i++) {
		for (int j = 0; j < (1 << f); j++) {
			if ((j >> i) & 1) continue;
			sets[0][j ^ (1 << i)] += sets[0][j];
