import java.util.*;
import java.io.*;

public class Main {
    static class ModNum {
        private int val;
        public static final int MOD = 1000000007;

        public ModNum() {
            this.val = 0;
        }

        public ModNum(long v) {
            this.val = (int)(v % MOD);
            if (this.val < 0) this.val += MOD;
        }

        public static int computeModInverse(int a, int m) {
            assert m > 0;
            if (m == 1) return 0;
            a %= m;
            if (a < 0) a += m;
            assert a != 0;
            if (a == 1) return 1;
            return m - computeModInverse(m, a) * m / a;
        }

        public ModNum invert() {
            return new ModNum(computeModInverse(this.val, MOD));
        }

        public ModNum add(ModNum o) {
            int res = this.val + o.val;
            if (res >= MOD) res -= MOD;
            return new ModNum(res);
        }

        public ModNum subtract(ModNum o) {
            int res = this.val - o.val;
            if (res < 0) res += MOD;
            return new ModNum(res);
        }

        public ModNum multiply(ModNum o) {
            long res = (long)this.val * o.val % MOD;
            return new ModNum(res);
        }

        public ModNum divide(ModNum o) {
            return this.multiply(o.invert());
        }

        public int toInt() {
            return this.val;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st;

        final int n = 6;
        ModNum[][] p = new ModNum[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                p[i][j] = new ModNum(0);
            }
        }

        int _n = Integer.parseInt(br.readLine());
        for (int i = 0; i < n; i++) {
            st = new StringTokenizer(br.readLine());
            for (int j = 0; j < _n; j++) {
                int a = Integer.parseInt(st.nextToken());
                p[i][j] = new ModNum(a).divide(new ModNum(100));
            }
        }

        final int f = 20;
        ModNum[][] sets = new ModNum[2][1 << f];
        for (int t = 0; t < 2; t++) {
            for (int j = 0; j < (1 << f); j++) {
                sets[t][j] = new ModNum(0);
            }
        }

        List<Integer>[] masks = new List[2];
        masks[0] = new ArrayList<>();
        masks[1] = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < i; j++) {
                for (int k = 0; k < j; k++) {
                    int maskVal = (1 << i) ^ (1 << j) ^ (1 << k);
                    masks[0].add(maskVal);
                    masks[1].add(((1 << n) - 1) ^ maskVal);
                }
            }
        }

        assert masks[0].size() == f;

        for (int t = 0; t < 2; t++) {
            for (int e = 0; e < (1 << (n / 2 * n)); e++) {
                ModNum prob = new ModNum(1);
                int[] edges = new int[n / 2];
                Arrays.fill(edges, 0);
                for (int i = 0; i < n / 2 * n; i++) {
                    boolean r = ((e >> i) & 1) == 1;
                    ModNum pp = p[(i / n) * 2 + t][i % n];
                    prob = r ? prob.multiply(pp) : prob.multiply(new ModNum(1).subtract(pp));
                    edges[i / n] |= (r ? 1 : 0) << (i % n);
                }
                int work_mask = 0;
                for (int a = 0; a < masks[t].size(); a++) {
                    int mask = masks[t].get(a);
                    int[] rArr = new int[n / 2];
                    for (int i = 0; i < n / 2; i++) {
                        rArr[i] = edges[i] & mask;
                    }
                    if (rArr[0] != 0 && rArr[1] != 0 && rArr[2] != 0) {
                        int total = rArr[0] | rArr[1] | rArr[2];
                        if (Integer.bitCount(total) == 3) {
                            int x = Integer.bitCount(rArr[0] | rArr[1]);
                            int y = Integer.bitCount(rArr[0] | rArr[2]);
                            int z = Integer.bitCount(rArr[1] | rArr[2]);
                            if (x >= 2 && y >= 2 && z >= 2) {
                                work_mask |= (1 << a);
                            }
                        }
                    }
                }
                sets[t][work_mask] = sets[t][work_mask].add(prob);
            }
        }

        for (int i = 0; i < f; i++) {
            for (int j = 0; j < (1 << f); j++) {
                if (((j >> i) & 1) == 1) continue;
                sets[0][j ^ (1 << i)] = sets[0][j ^ (1 << i)].add(sets[0][j]);
            }
        }

        ModNum answer = new ModNum(0);
        for (int j = 0; j < (1 << f); j++) {
            answer = answer.add(sets[0][j].multiply(sets[1][((1 << f) - 1) ^ j]));
        }
        answer = new ModNum(1).subtract(answer);
        System.out.println(answer.toInt());
    }
}
